package com.example.techfix.activities;
import android.os.Bundle;import android.widget.Toast;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.example.techfix.R;import com.example.techfix.adapters.BranchAdapter;import com.example.techfix.database.DatabaseHelper;import com.example.techfix.models.Branch;import java.util.ArrayList;import java.util.HashMap;import java.util.Map;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;
public class BranchesActivity extends AppCompatActivity{private final ExecutorService io=Executors.newSingleThreadExecutor();private DatabaseHelper db;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_branches);db=new DatabaseHelper(this);findViewById(R.id.btnBranchesBack).setOnClickListener(v->finish());load();}private void load(){io.execute(()->{try{java.util.List<Branch> branches=db.getAllBranches();Map<Integer,java.util.List<String>> techs=new HashMap<>();for(Branch x:branches)techs.put(x.getId(),db.getActiveTechnicians(x.getId()));runOnUiThread(()->{RecyclerView r=findViewById(R.id.rvBranches);r.setLayoutManager(new LinearLayoutManager(this));r.setAdapter(new BranchAdapter(branches,techs));});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Unable to load branches",Toast.LENGTH_LONG).show());}});}@Override protected void onDestroy(){io.shutdown();db.close();super.onDestroy();}}
